"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3356],{40106:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"store","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"LaneScaler\\n"}],"function_type":"static","source":{"line":78,"path":"src/internal/LaneScaler.luau"}},{"name":"current","desc":"The lane count to use for `partition` right now.\\n\\nCached, because this is read on the enqueue path. A stale read is harmless:\\nthe ticket goes into the previous count\'s lane, which its writer keeps\\nscanning and which the new count\'s workers read as a legacy map.","params":[{"name":"self","desc":"","lua_type":"LaneScaler"},{"name":"partition","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"LaneState\\n"}],"function_type":"static","source":{"line":115,"path":"src/internal/LaneScaler.luau"}},{"name":"observe","desc":"Feeds one scan\'s result in. Returns the new count if this observation caused\\na change, otherwise `nil`.","params":[{"name":"self","desc":"","lua_type":"LaneScaler"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"depth","desc":"Candidates the scan returned.","lua_type":"number"},{"name":"cap","desc":"The batch size it asked for; reaching it means the lane is saturated.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","source":{"line":148,"path":"src/internal/LaneScaler.luau"}},{"name":"_apply","desc":"Moves a partition to `target`, if nobody beat us to it and the cooldown has\\nelapsed. The compare-and-set is what makes several servers proposing at once\\nsafe: exactly one wins and the rest see the result on their next read.","params":[{"name":"self","desc":"","lua_type":"LaneScaler"},{"name":"partition","desc":"","lua_type":"string"},{"name":"from","desc":"","lua_type":"number"},{"name":"target","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","private":true,"source":{"line":195,"path":"src/internal/LaneScaler.luau"}},{"name":"draining","desc":"Whether the count that `state` replaced could still hold live tickets. Once\\nfalse, workers stop reading legacy maps.","params":[{"name":"self","desc":"","lua_type":"LaneScaler"},{"name":"state","desc":"","lua_type":"LaneState"}],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","source":{"line":238,"path":"src/internal/LaneScaler.luau"}}],"properties":[],"types":[],"name":"LaneScaler","desc":"Decides how many lanes a partition should have, and moves it there safely.\\n\\n### The shared record\\n\\nOne MemoryStore entry per partition holds `{ count, previous, changedAt }`.\\nEvery server reads it (cached for `LANE_STATE_REFRESH` seconds) to know where\\nto write tickets, and any worker may propose a change through a\\ncompare-and-set. There is no coordinator.\\n\\n### Why resizing is safe\\n\\nThe count is stamped into every lane key, so servers that disagree about it\\nwrite to *different* key spaces rather than corrupting one. A ticket is\\nalways readable in the lane its writer put it in \u2014 the writer keeps scanning\\nthat lane for as long as the ticket lives, and workers on the new count also\\nread the old maps through `Lanes.legacyMaps`. Nothing is stranded, and the\\ntwo pools see each other throughout.\\n\\nThe cooldown between changes is a full `ticketExpiration`. That is deliberate:\\nit guarantees every ticket written under an abandoned count has expired or\\nmatched before that count can come back into use, so a lane name is never\\nreused while stale entries sit in it.\\n\\nCounts the scaler chooses are always powers of two, because it only ever\\nstarts at one and doubles or halves. That is what makes `Lanes.legacyMaps`\\nexact. A **pinned** count is under no such constraint \u2014 it never resizes, so\\nit has no previous count to map from.\\n\\n### When it changes\\n\\nEach worker judges only the lane it holds. Lanes are hashed uniformly, so one\\nlane\'s depth times the count estimates the whole queue.\\n\\n- **Grow** (double) after `LANE_SATURATED_PASSES` consecutive scans that come\\n  back at the batch cap. A saturated lane means the worker is only seeing the\\n  oldest slice of it, which biases matching.\\n- **Shrink** (halve) after `LANE_STARVED_PASSES` consecutive scans below\\n  `LANE_STARVED_DEPTH`, when the count is above 1. Over-sharding is the worse\\n  failure: it scatters a thin queue so nobody matches at all.\\n\\nBoth directions are gated on consecutive observations, so a single burst or\\nlull does not move anything.","source":{"line":49,"path":"src/internal/LaneScaler.luau"}}')}}]);